import pytest
from taf.ul.ettf.resources.expectations.rrc.carrier_aggregation import SCellToAddMod


@pytest.fixture
def scell():
    return SCellToAddMod()


def assert_match(template, value):
    matching_result = template.matches(value)
    assert [] == matching_result.mismatches
    assert matching_result


def assert_no_match(template, value):
    matching_result = template.matches(value)
    assert [] != matching_result.mismatches
    assert not matching_result


PACKET = {
    "SCellToAddMod-r10": {
        "sCellIndex-r10": 2,
        "cellIdentification-r10": {
            "dl-CarrierFreq-r10": 2850,
            "physCellId-r10": 2
        },
        "radioResourceConfigCommonSCell-r10": {
            "ul-Configuration-r10": {
                "ul-FreqInfo-r10": {
                    "additionalSpectrumEmissionSCell-r10": 1,
                    "ul-Bandwidth-r10": {},
                    "ul-CarrierFreq-r10": 20850
                },
            },
        },
        "radioResourceConfigDedicatedSCell-r10": {
            "physicalConfigDedicatedSCell-r10": {
                "ul-Configuration-r10": {
                    "cqi-ReportConfigSCell-r10": {
                        "cqi-ReportModeAperiodic-r10": {},
                        "cqi-ReportPeriodicSCell-r10": {
                            "setup": {
                                "cqi-FormatIndicatorPeriodic-r10": {
                                    "widebandCQI-r10": {}
                                },
                                "cqi-PUCCH-ResourceIndex-r10": 24,
                                "cqi-pmi-ConfigIndex": 81,
                                "ri-ConfigIndex": 1,
                                "simultaneousAckNackAndCQI": 'true'
                            }
                        },
                        "nomPDSCH-RS-EPRE-Offset-r10": {}
                    }
                },
                "nonUL-Configuration-r10": {
                    "antennaInfo-r10": {
                        "ue-TransmitAntennaSelection": {
                            "release": 'null'
                        },
                        "transmissionMode-r10": 0,
                        "codebookSubsetRestriction-r10": "00000000ffffffff"
                    },
                    "pdsch-ConfigDedicated-r10": {
                        "p-a": {}
                    },
                    "crossCarrierSchedulingConfig-r10": {
                        "schedulingCellInfo-r10": {
                            "own-r10": {
                                "cif-Presence-r10": 'false'
                            }
                        }
                    }
                }
            }
        },
        "antennaInfoDedicatedSCell-v10i0": {
            "maxLayersMIMO-r10": 1
        }
    }
}


def ul_configuration_template(ul_carrier_freq_value=20850):
    return {
        "ul-Configuration-r10": {
            "ul-FreqInfo-r10": {
                "additionalSpectrumEmissionSCell-r10": 1,
                "ul-Bandwidth-r10": {},
                "ul-CarrierFreq-r10": ul_carrier_freq_value
            },
        }
    }


def test_should_create_scell_index_container(scell):
    scell.with_scell_index(scell_index=2)
    assert_match(scell(), PACKET)


def test_should_create_cell_identification_container(scell):
    scell.with_cell_identification(cell_identification={
        "dl-CarrierFreq-r10": 2850,
        "physCellId-r10": 2
    })
    assert_match(scell(), PACKET)


def test_should_create_antena_info_dedicated_scell_container(scell):
    scell.with_antenna_info_dedicated_scell(layers='fourLayers')
    assert_match(scell(), PACKET)


def test_should_create_rrc_config_common_scell_container(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template())
    assert_match(scell(), PACKET)


def test_should_create_physical_resource_config_dedicated_scell_containing_csr_layers(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template()).\
        with_physical_resource_config_dedicated_scell_containing_csr_layers(csr_layers='two_layers', tm_mode='tm1')
    assert_match(scell(), PACKET)


def test_should_create_physical_resource_config_dedicated_scell(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template()).\
        with_physical_resource_config_dedicated_scell()
    assert_match(scell(), PACKET)


def test_should_create_omitted_antenna_info_dedicated_scell(scell):
    scell.with_antenna_info_dedicated_scell()
    assert_match(scell(), {"SCellToAddMod-r10": {}})


def test_should_fail_in_matching_scell_index_container(scell):
    scell.with_scell_index(scell_index=666)
    assert_no_match(scell(), PACKET)


def test_should_fail_in_matching_cell_identification_container(scell):
    scell.with_cell_identification(cell_identification={
        "dl-CarrierFreq-r10": 666,
        "physCellId-r10": 666
    })
    assert_no_match(scell(), PACKET)


def test_should_fail_in_matching_antena_info_dedicated_scell_container(scell):
    scell.with_antenna_info_dedicated_scell(layers='twoLayers')
    assert_no_match(scell(), PACKET)


def test_should_fail_in_matching_rrc_config_common_scell_container(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template(10850))
    assert_no_match(scell(), PACKET)


def test_should_fail_in_matching_physical_resource_config_dedicated_scell_containing_csr_layers(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template()).\
        with_physical_resource_config_dedicated_scell_containing_csr_layers(csr_layers='two_layers_2x2', tm_mode='tm1')
    assert_no_match(scell(), PACKET)


def test_should_fail_in_matching_omitted_antenna_info_dedicated_scell(scell):
    scell.with_radio_resource_config_common_scell(ul_configuration=ul_configuration_template()).\
        with_antenna_info_dedicated_scell()
    assert_no_match(scell(), PACKET)
